  const SLOTS = ['head', 'chest', 'legs', 'feet', 'sword', 'shield'];
  const DRAW_ORDER = ['legs', 'feet', 'chest', 'hair', 'head', 'shield', 'sword'];
  const HAIR_STYLES = [['short', 'ショート'], ['spiky', 'ツンツン'], ['long', 'ロング'], ['pony', 'ポニーテール'], ['bob', 'ボブ']];
  function rectsOf(rows, pal) {
    let r = '';
    rows.forEach((row, y) => {
      let x = 0;
      while (x < row.length) {
        const ch = row[x];
        if (!pal[ch]) { x++; continue; }
        let n = 1;
        while (row[x + n] === ch) n++;
        r += '<rect x="' + x + '" y="' + y + '" width="' + n + '" height="1" fill="' + pal[ch] + '"/>';
        x += n;
      }
    });
    return r;
  }
  const K = '#1a1020';
  function layerPal(slot, key, look) {
    const skin = HERO_PAL.skins[look.skin] || HERO_PAL.skins[0];
    return Object.assign({ k: K, s: skin.s, Y: '#f2c14e' }, HERO_PAL.art[slot][key] || {});
  }
  // art: { head: '0'〜'3' | 'fire' | 'dark' | 'ice', ... }  look: { hair, color, skin }  aura: 'fire' | 'dark' | 'ice' | null
  function hero(art, size, look, aura) {
    const a = Object.assign({ head: '0', chest: '0', legs: '0', feet: '0', sword: '0', shield: '0' }, art || {});
    const lk = Object.assign({ hair: 'short', color: 0, skin: 0 }, look || {});
    const skin = HERO_PAL.skins[lk.skin] || HERO_PAL.skins[0];
    const hc = HERO_PAL.hairs[lk.color] || HERO_PAL.hairs[0];
    let r = aura ? rectsOf(HERO.aura[aura], HERO_PAL.aura[aura]) : '';
    r += rectsOf(HERO.base, Object.assign({}, HERO_PAL.base, skin, { B: hc[2] }));
    DRAW_ORDER.forEach(sl => {
      if (sl === 'hair') { r += rectsOf(HERO.hair[lk.hair] || HERO.hair.short, { k: K, h: hc[1], H: hc[2], Y: '#f2c14e' }); return; }
      const key = String(a[sl]);
      r += rectsOf(HERO.art[sl][key] || HERO.art[sl]['0'], layerPal(sl, key, lk));
    });
    return '<svg class="hero-sprite' + (aura ? ' aura-' + aura : '') + '" width="' + size + '" height="' + (size * 1.2) + '" viewBox="0 0 20 24" shape-rendering="crispEdges" aria-hidden="true">' + r + '</svg>';
  }
  // 装備のアイコン（その部位の絵がある範囲だけを切り出して、正方形に拡大して描く）
  function bboxOf(rowsList) {
    let x0 = 99, y0 = 99, x1 = -1, y1 = -1;
    rowsList.forEach(rows => rows.forEach((row, y) => [...row].forEach((ch, x) => {
      if (ch !== '.' && ch !== ' ') { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
    })));
    return [x0, y0, x1 - x0 + 1, y1 - y0 + 1];
  }
  function gearIcon(slot, key, size, look) {
    const lk = Object.assign({ hair: 'short', color: 0, skin: 0 }, look || {});
    key = String(key);
    const rows = HERO.art[slot][key] || HERO.art[slot]['0'];
    const list = slot === 'head' ? [rows, HERO.base.slice(0, 10)] : [rows];
    let r = slot === 'head' ? rectsOf(HERO.base, Object.assign({}, HERO_PAL.base, HERO_PAL.skins[0], { B: '#4a2a12' })) : '';
    r += rectsOf(rows, layerPal(slot, key, lk));
    const [x, y, w, h] = bboxOf(list);
    const sz = Math.max(w, h) + 1;
    const ox = x - (sz - w) / 2, oy = y - (sz - h) / 2;
    return '<svg width="' + size + '" height="' + size + '" viewBox="' + ox + ' ' + oy + ' ' + sz + ' ' + sz + '" shape-rendering="crispEdges" aria-hidden="true">' + r + '</svg>';
  }


