  const ICON_KEYS = Object.keys(ICONS).filter(k => !['sword', 'shield', 'gear', 'mail', 'coin', 'potion', 'bomb', 'xpbook', 'charm', 'gem', 'chest', 'bag', 'goldbag', 'meat', 'cookie', 'fruit'].includes(k));
  function icon(key, size = 28) {
    const ic = ICONS[key];
    if (!ic) return null;
    return svg(ic.rows, ic.pal, size, { cls: 'px-icon' });
  }
  function boss(i, size, silhouette) {
    const b = BOSSES[i % BOSSES.length];
    return svg(b.rows, b.pal, size, { cls: 'boss-sprite', silhouette });
  }

  window.Sprites = { svg, layer, hero, gearIcon, icon, boss, BOSSES, BOSS_ORDER, ICONS, ICON_KEYS, SLOTS, HAIR_STYLES, HAIR_COLORS: HERO_PAL.hairs, SKINS: HERO_PAL.skins };
